            if (null === $uid) {
                throw ConstraintException::ofError('not-null', ['uid'], [null]);
            }
            $rawTenant = $row['tenant'] ?? null;
            if (null === $rawTenant) {
                throw ConstraintException::ofError('not-null', ['tenant'], [null]);
            }
            $tenant = new TenantRef(uid: $rawTenant);
            // throws validation exception if is null.
            $key = ConsentPurposeKeyVO::fromString($row['key'] ?? '');
            $title = $row['title'] ?? null;
            if (null === $title) {
                throw ConstraintException::ofError('not-null', ['title'], [null]);
            }
            $description = $row['description'] ?? null;
            if (null === $description) {
                throw ConstraintException::ofError('not-null', ['description'], [null]);
            }
            $required = isset($row['required']) ? !! $row['required'] : null;
            if (null === $required) {
                throw ConstraintException::ofError('not-null', ['required'], [null]);
            }
            $activationDate = $row['activation_date'] ? new \DateTimeImmutable($row['activation_date']) : null;
            if (null === $activationDate) {
                throw ConstraintException::ofError('not-null', ['activationDate'], [null]);
            }
            $version = $row['version'] ?? null;
            return new ConsentPurpose(
                uid: $uid,
                tenant: $tenant,
                key: $key,
                title: $title,
                description: $description,
                required: $required,
                activationDate: $activationDate,
                version: $version,
